mapper.update:
update cms_alarm_def
   set alarm_nm = #{d.alarmNm}, severity = #{d.severity}, symptom_id = #{d.symptomId}, auto_bm_yn = #{d.autoBmYn},
       use_yn = #{d.useYn}, remark = #{d.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where def_id = #{d.defId} and row_ver = #{d.rowVer}

mapper.select:
select 

 order by l.raised_at desc, l.alarm_id desc
 limit #{limit}
